/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

/** An element's box for one gesture, from `measuredBox`. */
export interface MeasuredBox {
  /** The box: measured the first time, and again only after the page scrolled or resized. */
  get: () => DOMRect;
  /** Stops watching the page. Call it when the gesture ends. */
  stop: () => void;
}

/**
 * An element's box, measured once for a gesture rather than on each of its
 * moves. Read after a move wrote to the page, `getBoundingClientRect` makes
 * the browser lay the page out on the spot, every frame. A scroll or a resize
 * during the gesture moves the element, so either one measures it again.
 */
export function measuredBox(element: Element): MeasuredBox {
  let box: DOMRect | null = null;
  const view = element.ownerDocument?.defaultView;
  const stale = () => {
    box = null;
  };
  view?.addEventListener("scroll", stale, { capture: true, passive: true });
  view?.addEventListener("resize", stale, { passive: true });
  return {
    get: () => {
      box ??= element.getBoundingClientRect();
      return box;
    },
    stop: () => {
      view?.removeEventListener("scroll", stale, { capture: true });
      view?.removeEventListener("resize", stale);
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

/** The number a typed text means: "-6", "-6 dB" or "12,5". */
const typedNumber = (text: string) => {
  const parsed = Number.parseFloat(text.trim().replace(",", "."));
  return Number.isFinite(parsed) ? parsed : null;
};

const INPUT_STYLE =
  "position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; border-radius: inherit; background: inherit; color: inherit; font: inherit; text-align: center; box-sizing: border-box";

/**
 * Lets the reader type a value into a control's readout: a double click on
 * it, or Enter or F2 while it has focus, lays a text field over it. Enter or
 * leaving the field gives the control the number typed, through its native
 * range input, as a drag would; Escape keeps the value. The framework keeps
 * drawing the readout's text under the field. `root` is the control's slot
 * (`knob`, `fader`). Returns what takes it away.
 */
export function editableReadout(readout: HTMLElement, root: string) {
  let field: HTMLInputElement | null = null;
  const positioned = readout.style.position;
  const finish = (text: string | null) => {
    if (!field) {
      return;
    }
    field.remove();
    field = null;
    readout.removeAttribute("data-editing");
    readout.style.position = positioned;
    readout.focus({ preventScroll: true });
    const typed = text === null ? null : typedNumber(text);
    const input = readout
      .closest(`[data-slot="${root}"]`)
      ?.querySelector<HTMLInputElement>('input[type="range"]');
    if (typed === null || !input) {
      return;
    }
    Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      "value"
    )?.set?.call(input, String(typed));
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  };
  const open = () => {
    if (field || readout.closest("[data-disabled]")) {
      return;
    }
    const text = readout.textContent?.trim() ?? "";
    field = document.createElement("input");
    field.type = "text";
    field.inputMode = "decimal";
    field.value = text;
    field.size = Math.max(text.length, 3);
    field.style.cssText = INPUT_STYLE;
    const label = readout.getAttribute("aria-label");
    if (label) {
      field.setAttribute("aria-label", label);
    }
    field.addEventListener("keydown", (event) => {
      event.stopPropagation();
      if (event.key === "Enter") {
        event.preventDefault();
        finish(field?.value ?? null);
      } else if (event.key === "Escape") {
        event.preventDefault();
        finish(null);
      }
    });
    field.addEventListener("blur", () => finish(field?.value ?? null));
    if (getComputedStyle(readout).position === "static") {
      readout.style.position = "relative";
    }
    readout.setAttribute("data-editing", "");
    readout.appendChild(field);
    field.focus({ preventScroll: true });
    field.select();
  };
  // A readout inside a thumb or a control must not also reset or drag it.
  const handleDoubleClick = (event: MouseEvent) => {
    event.stopPropagation();
    open();
  };
  const handleKeyDown = (event: KeyboardEvent) => {
    if (
      event.target === readout &&
      (event.key === "Enter" || event.key === "F2")
    ) {
      event.preventDefault();
      open();
    }
  };
  const handlePointerDown = (event: PointerEvent) => event.stopPropagation();
  const tabIndex = readout.getAttribute("tabindex");
  readout.tabIndex = 0;
  readout.setAttribute("aria-keyshortcuts", "Enter");
  readout.setAttribute("data-editable", "");
  readout.addEventListener("dblclick", handleDoubleClick);
  readout.addEventListener("keydown", handleKeyDown);
  readout.addEventListener("pointerdown", handlePointerDown);
  return () => {
    finish(null);
    readout.removeEventListener("dblclick", handleDoubleClick);
    readout.removeEventListener("keydown", handleKeyDown);
    readout.removeEventListener("pointerdown", handlePointerDown);
    readout.removeAttribute("aria-keyshortcuts");
    readout.removeAttribute("data-editable");
    if (tabIndex === null) {
      readout.removeAttribute("tabindex");
    } else {
      readout.setAttribute("tabindex", tabIndex);
    }
  };
}

import {
  createChange,
  css,
  dispatch,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import { clamp } from "@ui-sdk/core/number";
import {
  type ChangeDetails,
  type CommitDetails,
  createGestures,
  definePrimitive,
  flag,
  sourceOf,
  VISUALLY_HIDDEN,
} from "../primitive";

export type { ChangeDetails, CommitDetails } from "../primitive";

/**
 * The step sequencer: a grid of steps to switch on and off, one row per
 * sound, painted by dragging, with a velocity bar under each step. It holds
 * two values, the pattern and the velocities, each controlled or its own.
 *
 * A cell and a velocity bar are written by the app with their `row` and their
 * `step`; the primitive keys them by the pair, as `cell`. The step being
 * played comes from a `source` and is marked on its cells straight in the
 * DOM, with `data-current`, so a clock ticking every step renders nothing.
 */

/** Which steps are on: a row per sound, a cell per step. */
export type Pattern = readonly (readonly boolean[])[];

/** Loudness per step, 0 to 1: a row per sound, like the pattern. A step it does not list is at full. */
export type Velocities = readonly (readonly number[])[];

/** A cell of the grid: its row and its step. */
export interface CellAddress {
  row: number;
  step: number;
}

/** The step being played, a live value an engine pushes to. */
export interface StepSource {
  getSnapshot: () => number;
  subscribe: (listener: () => void) => () => void;
}

/** What a step plays at until it is set. */
const DEFAULT_VELOCITY = 1;
/** What the arrow keys change a velocity by; Page Up and Page Down move five times as far. */
const VELOCITY_STEP = 0.05;
const VELOCITY_LARGE_STEP = 0.25;
/** A drag between two frames is followed in steps this long, in px, so a quick stroke misses no cell. */
const STROKE_SAMPLE_PX = 4;

const EMPTY: readonly never[] = [];

const cellKey = ({ row, step }: CellAddress) => `${row}:${step}`;

const isOn = (pattern: Pattern, { row, step }: CellAddress) =>
  pattern[row]?.[step] === true;

const velocityAt = (velocities: Velocities, { row, step }: CellAddress) =>
  velocities[row]?.[step] ?? DEFAULT_VELOCITY;

/** `pattern` with one cell set. */
const setCell = (pattern: Pattern, { row, step }: CellAddress, on: boolean) =>
  pattern.map((cells, at) =>
    at === row
      ? cells.map((cell, index) => (index === step ? on : cell))
      : [...cells]
  );

/** `velocities` with one step set, grown to `rows` by `steps`. */
const setVelocity = (
  velocities: Velocities,
  { row, step }: CellAddress,
  velocity: number,
  rows: number,
  steps: number
) =>
  Array.from({ length: rows }, (_, rowAt) =>
    Array.from({ length: steps }, (_step, stepAt) =>
      rowAt === row && stepAt === step
        ? velocity
        : velocityAt(velocities, { row: rowAt, step: stepAt })
    )
  );

/** The velocity a press at `clientY` sets on a bar: its bottom is silent, its top full. */
const velocityAtY = (box: DOMRect, clientY: number) =>
  box.height <= 0
    ? DEFAULT_VELOCITY
    : clamp((box.bottom - clientY) / box.height, 0, 1);

/** Where an arrow, Home or End key takes the focus from `from`, kept inside the grid. */
function moveFocus(
  from: CellAddress,
  key: string,
  rows: number,
  steps: number,
  ctrlKey: boolean
): CellAddress | null {
  const last = { row: Math.max(0, rows - 1), step: Math.max(0, steps - 1) };
  switch (key) {
    case "ArrowLeft":
      return { ...from, step: Math.max(0, from.step - 1) };
    case "ArrowRight":
      return { ...from, step: Math.min(last.step, from.step + 1) };
    case "ArrowUp":
      return { ...from, row: Math.max(0, from.row - 1) };
    case "ArrowDown":
      return { ...from, row: Math.min(last.row, from.row + 1) };
    case "Home":
      return ctrlKey ? { row: 0, step: 0 } : { ...from, step: 0 };
    case "End":
      return ctrlKey ? last : { ...from, step: last.step };
    default:
      return null;
  }
}

/** The cell whose element holds the point. */
function cellAtPoint(
  nodes: ReadonlyMap<string, Element>,
  x: number,
  y: number
): CellAddress | null {
  for (const [key, node] of nodes) {
    const box = node.getBoundingClientRect();
    if (x >= box.left && x < box.right && y >= box.top && y < box.bottom) {
      const [row, step] = key.split(":").map(Number);
      return { row: row ?? 0, step: step ?? 0 };
    }
  }
  return null;
}

/** The points of a stroke from `from` to `to`, close enough together to touch every cell it crosses. */
function strokePoints(from: { x: number; y: number }, x: number, y: number) {
  const count = Math.max(
    1,
    Math.ceil(Math.hypot(x - from.x, y - from.y) / STROKE_SAMPLE_PX)
  );
  return Array.from({ length: count }, (_, index) => {
    const t = (index + 1) / count;
    return { x: from.x + (x - from.x) * t, y: from.y + (y - from.y) * t };
  });
}

export interface SequencerPrimitiveOptions {
  /** Uncontrolled starting pattern: a row per sound, each a list of steps. */
  defaultValue?: Pattern;
  /** Uncontrolled starting velocities. */
  defaultVelocities?: Velocities;
  disabled?: boolean;
  onValueChange?: (value: boolean[][], details: ChangeDetails) => void;
  onValueCommitted?: (value: boolean[][], details: CommitDetails) => void;
  onVelocityChange?: (velocities: number[][], details: ChangeDetails) => void;
  onVelocityCommitted?: (
    velocities: number[][],
    details: CommitDetails
  ) => void;
  /** The step being played, a live value followed without a render. */
  source?: StepSource;
  /** The pattern: a row per sound, each a list of steps. */
  value?: Pattern;
  /** How loud each step plays, 0 to 1, a row per sound like the pattern. */
  velocities?: Velocities;
}

export interface SequencerState {
  disabled: boolean;
  /**
   * The pattern and the velocities as the gesture under way left them: a
   * controlled value that lags behind must not pull them back mid-gesture.
   * The options take over again whenever they change.
   */
  draftValue: Pattern | null;
  draftVelocities: Velocities | null;
  /** Whether a pointer is painting cells. */
  painting: boolean;
  /** The step being played, followed without a render. */
  source: StepSource | undefined;
  /** The cell the arrow keys start from: the one tab stop among the cells. */
  tabStop: CellAddress;
  /** The pattern the app holds, or the sequencer's own. */
  value: Pattern;
  /** The velocities the app holds, or the sequencer's own. */
  velocities: Velocities;
}

/** What a view draws the sequencer from. */
export interface SequencerSnapshot {
  disabled: boolean;
  painting: boolean;
  rows: number;
  steps: number;
  /** The tab stop, kept inside the grid whatever its size now. */
  tabStop: CellAddress;
  value: Pattern;
  velocities: Velocities;
}

const views = new WeakMap<SequencerState, SequencerSnapshot>();

/** What the parts draw from `state`, worked out once per state. */
export function viewOf(state: SequencerState): SequencerSnapshot {
  const cached = views.get(state);
  if (cached) {
    return cached;
  }
  const rows = state.value.length;
  const steps = state.value[0]?.length ?? 0;
  const view: SequencerSnapshot = {
    disabled: state.disabled,
    painting: state.painting,
    rows,
    steps,
    tabStop: {
      row: Math.min(state.tabStop.row, Math.max(0, rows - 1)),
      step: Math.min(state.tabStop.step, Math.max(0, steps - 1)),
    },
    value: state.value,
    velocities: state.velocities,
  };
  views.set(state, view);
  return view;
}

/** What a part's className, style and children functions read of the grid. */
export interface SequencerRootState {
  disabled: boolean;
  /** Whether a pointer is painting cells. */
  painting: boolean;
  /** How many rows the pattern has: write a row for each. */
  rows: number;
  /** How many steps a row has: write a cell for each. */
  steps: number;
}

/** What a cell reads of itself. */
export interface CellState {
  disabled: boolean;
  /** Whether the step is on: also `aria-pressed`. */
  on: boolean;
}

/** What a velocity bar reads of itself. */
export interface VelocityState {
  disabled: boolean;
  on: boolean;
  /** How loud the step plays, 0 to 1. */
  velocity: number;
}

/** What a sequencer's `api` gives an adapter. */
export interface SequencerApi {
  /** The cells' elements by `row:step`, which a paint reads to find the one under the pointer. */
  cells: Map<string, HTMLElement>;
  /** Which key a `"key"` prop is keyed by. */
  internal: { keyOf: (cell: unknown) => string };
  /** Where an arrow, Home or End key takes the focus from `from`: the new tab stop, or null when the key is not the grid's. */
  moveFocusFrom: (
    from: CellAddress,
    event: KeyboardEvent
  ) => CellAddress | null;
  /** The step being played, kept here so a cell that binds later marks itself. */
  playing: { step: number | null };
  /** Starts a press on a cell: a drag paints the cells the pointer crosses with the opposite of the first one's state. */
  pressCell: (
    cell: CellAddress,
    event: PointerEvent,
    root: HTMLElement
  ) => void;
  /** Starts a press on a step's velocity bar: a drag draws the velocities of the steps it crosses in that row. */
  pressVelocity: (
    cell: CellAddress,
    event: PointerEvent,
    root: HTMLElement
  ) => void;
  /** Moves the tab stop, without focusing anything. */
  setTabStop: (cell: CellAddress) => void;
  /** Sets one step's velocity and commits it at once: a key, an input or a reset. */
  setVelocity: (
    cell: CellAddress,
    velocity: number,
    reason: string,
    event: Event
  ) => void;
  /** Flips a cell from the keyboard, and commits it. */
  toggleCell: (cell: CellAddress, event: KeyboardEvent) => void;
  /** The velocity bars' elements by `row:step`. */
  velocities: Map<string, HTMLElement>;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The props of a part at one step of one row. */
interface AtStep extends PartProps {
  /** `row:step`, which keys the part: the adapter writes it. */
  cell: string;
  row: number;
  step: number;
}

/** The sequencer's slots, by name, with the props and the public state of each. */
export type SequencerSlots = {
  cell: SlotDefinition<SequencerState, SequencerApi, AtStep, CellState>;
  root: SlotDefinition<
    SequencerState,
    SequencerApi,
    PartProps,
    SequencerRootState
  >;
  row: SlotDefinition<
    SequencerState,
    SequencerApi,
    PartProps & { index: number },
    SequencerRootState
  >;
  velocity: SlotDefinition<SequencerState, SequencerApi, AtStep, VelocityState>;
  velocityInput: SlotDefinition<
    SequencerState,
    SequencerApi,
    {
      /** `row:step`, which keys the input: the adapter writes it. */
      cell: string;
      getAriaValueText?: (velocity: number) => string;
      row: number;
      step: number;
    },
    object
  >;
};

/**
 * The type of `sequencer`, written out: the kernel's own types its inferred
 * type would name are not exported, so a declaration could not print it.
 */
export interface SequencerPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: SequencerSlots;
  (
    initialOptions: SequencerPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: SequencerApi;
    get: () => SequencerState;
    types: {
      api: SequencerApi;
      options: SequencerPrimitiveOptions;
      slots: SequencerSlots;
      state: SequencerState;
    };
  };
}

const rootState = (state: SequencerState): SequencerRootState => {
  const view = viewOf(state);
  return {
    disabled: view.disabled,
    painting: view.painting,
    rows: view.rows,
    steps: view.steps,
  };
};

const addressOf = (props: { row?: number; step?: number }): CellAddress => ({
  row: Number(props.row ?? 0),
  step: Number(props.step ?? 0),
});

/** The root element a gesture follows, found from a part inside it. */
const rootOf = (el: HTMLElement | undefined) =>
  el?.closest<HTMLElement>('[data-slot="sequencer"]') ?? undefined;

/** One pointer gesture: a paint on the cells, or a draw on one row's velocity bars. */
interface Gesture {
  /** Whether it changed anything; if so its end commits. */
  changed: boolean;
  kind: "paint" | "velocity";
  /** Where the pointer was at the last move. */
  last: { x: number; y: number };
  /** The state a paint sets each cell it crosses to. */
  on: boolean;
  /** The row a velocity draw stays in. */
  row: number;
}

/** What the options give the state, whatever the gestures did: a draft gives way to them. */
const optionsState = (options: SequencerPrimitiveOptions) => ({
  disabled: options.disabled ?? false,
  draftValue: null,
  draftVelocities: null,
  source: options.source,
  ...(options.value === undefined ? {} : { value: options.value }),
  ...(options.velocities === undefined
    ? {}
    : { velocities: options.velocities }),
});

export const sequencer: SequencerPrimitive = definePrimitive({
  api: (context) => {
    const change = createChange(context);
    const state = () => context.store.get() as SequencerState;
    const set = (next: Partial<SequencerState>) =>
      context.store.set(next as never);
    const options = () => context.options() as SequencerPrimitiveOptions;
    const cells = new Map<string, HTMLElement>();
    const velocities = new Map<string, HTMLElement>();
    const gestures = createGestures<Gesture>(context);

    /** The pattern and velocities as the gesture under way left them. */
    const currentValue = () => state().draftValue ?? state().value;
    const currentVelocities = () =>
      state().draftVelocities ?? state().velocities;

    /** Sets one cell, if it differs; says whether the change went through. */
    const setCellTo = (
      cell: CellAddress,
      on: boolean,
      reason: string,
      event: Event
    ) => {
      const current = currentValue();
      if (isOn(current, cell) === on) {
        return false;
      }
      const next = setCell(current, cell, on);
      const source = sourceOf(event);
      if (
        !change(
          "value",
          next as never,
          {
            event,
            reason,
            ...(source ? { source } : {}),
          } as never
        )
      ) {
        return false;
      }
      set({ draftValue: next });
      return true;
    };

    const commitValue = (reason: string, event: Event) =>
      dispatch(context, "onValueCommitted", currentValue(), { event, reason });

    /** Sets one step's velocity, if it differs; says whether the change went through. */
    const changeVelocity = (
      cell: CellAddress,
      velocity: number,
      reason: string,
      event: Event
    ) => {
      const current = currentVelocities();
      const pattern = currentValue();
      const next = setVelocity(
        current,
        cell,
        clamp(velocity, 0, 1),
        pattern.length,
        pattern[0]?.length ?? 0
      );
      if (next[cell.row]?.[cell.step] === velocityAt(current, cell)) {
        return false;
      }
      const source = sourceOf(event);
      // `createChange` would call `onVelocitiesChange`: this one is named by hand.
      if (
        dispatch(context, "onVelocityChange", next, {
          event,
          reason,
          ...(source ? { source } : {}),
        })
      ) {
        return false;
      }
      // Controlled velocities wait for the app to give them back.
      set(
        options().velocities === undefined
          ? { draftVelocities: next, velocities: next }
          : { draftVelocities: next }
      );
      return true;
    };

    const commitVelocities = (reason: string, event: Event) =>
      dispatch(context, "onVelocityCommitted", currentVelocities(), {
        event,
        reason,
      });

    /** Sets the velocity of the step under a point, in the row being drawn. */
    const drawVelocityAt = (
      row: number,
      x: number,
      y: number,
      event: PointerEvent
    ) => {
      for (const [key, node] of velocities) {
        const [nodeRow, nodeStep] = key.split(":").map(Number);
        const box = node.getBoundingClientRect();
        if (nodeRow === row && x >= box.left && x < box.right) {
          return changeVelocity(
            { row, step: nodeStep ?? 0 },
            velocityAtY(box, y),
            "drag",
            event
          );
        }
      }
      return false;
    };

    /** Applies one point of a stroke; says whether it changed anything. */
    const strokeAt = (
      gesture: Gesture,
      x: number,
      y: number,
      event: PointerEvent
    ) => {
      if (gesture.kind === "velocity") {
        return drawVelocityAt(gesture.row, x, y, event);
      }
      const crossed = cellAtPoint(cells, x, y);
      return crossed !== null && setCellTo(crossed, gesture.on, "paint", event);
    };

    /** Ends a gesture, committing what it changed. */
    const finish = (gesture: Gesture, event: PointerEvent) => {
      if (gesture.kind === "paint") {
        set({ painting: false });
        if (gesture.changed) {
          commitValue("paint", event);
        }
      } else if (gesture.changed) {
        commitVelocities("drag", event);
      }
      set({ draftValue: null, draftVelocities: null });
    };

    /** Follows a press on `root` until it lifts, drawing the stroke between moves. */
    const follow = (root: HTMLElement, event: PointerEvent, gesture: Gesture) =>
      gestures.start(root, event, gesture, {
        onEnd: (end) => finish(gesture, end),
        onMove: (move) => {
          for (const point of strokePoints(
            gesture.last,
            move.clientX,
            move.clientY
          )) {
            if (strokeAt(gesture, point.x, point.y, move)) {
              gesture.changed = true;
            }
          }
          gesture.last = { x: move.clientX, y: move.clientY };
        },
      });

    /** Whether a press may start a gesture, ending a stale one of the same pointer first. */
    const accepts = (event: PointerEvent) =>
      !state().disabled &&
      event.button === 0 &&
      gestures.accepts(event, (stale) => finish(stale, event));

    return {
      cells,
      internal: { keyOf: (cell: unknown) => String(cell) },
      moveFocusFrom: (from: CellAddress, event: KeyboardEvent) => {
        const value = currentValue();
        const next = moveFocus(
          from,
          event.key,
          value.length,
          value[0]?.length ?? 0,
          event.ctrlKey || event.metaKey
        );
        if (next) {
          set({ tabStop: next });
        }
        return next;
      },
      playing: { step: null as number | null },
      pressCell: (
        cell: CellAddress,
        event: PointerEvent,
        root: HTMLElement
      ) => {
        if (!accepts(event)) {
          return;
        }
        const gesture: Gesture = {
          changed: false,
          kind: "paint",
          last: { x: event.clientX, y: event.clientY },
          on: !isOn(currentValue(), cell),
          row: cell.row,
        };
        set({ painting: true });
        gesture.changed = setCellTo(cell, gesture.on, "press", event);
        follow(root, event, gesture);
      },
      pressVelocity: (
        cell: CellAddress,
        event: PointerEvent,
        root: HTMLElement
      ) => {
        if (!accepts(event)) {
          return;
        }
        const gesture: Gesture = {
          changed: false,
          kind: "velocity",
          last: { x: event.clientX, y: event.clientY },
          on: false,
          row: cell.row,
        };
        gesture.changed = drawVelocityAt(
          cell.row,
          event.clientX,
          event.clientY,
          event
        );
        follow(root, event, gesture);
      },
      setTabStop: (cell: CellAddress) => set({ tabStop: cell }),
      setVelocity: (
        cell: CellAddress,
        velocity: number,
        reason: string,
        event: Event
      ) => {
        if (changeVelocity(cell, velocity, reason, event)) {
          commitVelocities(reason, event);
        }
        set({ draftVelocities: null });
      },
      toggleCell: (cell: CellAddress, event: KeyboardEvent) => {
        if (setCellTo(cell, !isOn(currentValue(), cell), "keyboard", event)) {
          commitValue("keyboard", event);
        }
        set({ draftValue: null });
      },
      velocities,
    };
  },
  controlled: ["value", "velocities"],
  name: "sequencer",
  options: {
    defaultValue: "value",
    defaultVelocities: "value",
    disabled: "boolean",
    onValueChange: "callback",
    onValueCommitted: "callback",
    onVelocityChange: "callback",
    onVelocityCommitted: "callback",
    source: "value",
    value: "value",
    velocities: "value",
  },
  slots: (slot) => ({
    cell: slot<AtStep, CellState>({
      attrs: (state: SequencerState, { props }) => {
        const cell = addressOf(props);
        const view = viewOf(state);
        const on = isOn(view.value, cell);
        const stop =
          view.tabStop.row === cell.row && view.tabStop.step === cell.step;
        return {
          "aria-pressed": String(on),
          "data-disabled": flag(view.disabled),
          "data-on": flag(on),
          "data-painting": flag(view.painting),
          "data-row": String(cell.row),
          "data-step": String(cell.step),
          disabled: flag(view.disabled),
          tabindex: stop ? "0" : "-1",
          type: "button",
        };
      },
      bind: (el, part) => {
        const cell = addressOf(part.props);
        const key = cellKey(cell);
        part.api.cells.set(key, el);
        el.toggleAttribute("data-current", part.api.playing.step === cell.step);
        return () => part.api.cells.delete(key);
      },
      on: {
        focus: (_event, { api, props }) => api.setTabStop(addressOf(props)),
        keydown: (event, { api, props, store }) => {
          if (store.get().disabled) {
            return;
          }
          const cell = addressOf(props);
          if (event.key === " " || event.key === "Enter") {
            event.preventDefault();
            api.toggleCell(cell, event);
            return;
          }
          const next = api.moveFocusFrom(cell, event);
          if (next) {
            event.preventDefault();
            api.cells.get(cellKey(next))?.focus({ preventScroll: true });
          }
        },
        pointerdown: (event, { api, el, props, store }) => {
          const root = rootOf(el);
          if (!root || store.get().disabled || event.button !== 0) {
            return;
          }
          event.preventDefault();
          const cell = addressOf(props);
          api.setTabStop(cell);
          el?.focus({ preventScroll: true });
          api.pressCell(cell, event, root);
        },
      },
      props: { cell: "key", row: "number", step: "number" },
      state: (state: SequencerState, { props }) => ({
        disabled: state.disabled,
        on: isOn(state.value, addressOf(props)),
      }),
    }),
    root: slot<object, SequencerRootState>({
      attrs: (state: SequencerState) => ({
        "data-disabled": flag(state.disabled),
        "data-painting": flag(state.painting),
        role: "group",
        // For a stylesheet to lay each row's cells out in a line.
        style: css({
          "--sequencer-steps": String(viewOf(state).steps),
          "touch-action": "none",
        }),
      }),
      // The step being played is marked on its cells without a render.
      bind: (_el, part) => {
        let watched: StepSource | undefined;
        let stop: () => void = () => undefined;
        const mark = (step: number | null, on: boolean) => {
          if (step === null) {
            return;
          }
          for (const [key, node] of part.api.cells) {
            if (key.endsWith(`:${step}`)) {
              node.toggleAttribute("data-current", on);
            }
          }
        };
        const follow = () => {
          const current = part.store.get();
          const step = current.source?.getSnapshot() ?? -1;
          const next =
            step >= 0 && step < viewOf(current).steps ? Math.floor(step) : null;
          const previous = part.api.playing.step;
          if (next !== previous) {
            mark(previous, false);
            part.api.playing.step = next;
            mark(next, true);
          }
        };
        const watch = () => {
          const { source } = part.store.get();
          if (source !== watched) {
            stop();
            watched = source;
            stop = source ? source.subscribe(follow) : () => undefined;
          }
          follow();
        };
        watch();
        const off = part.store.subscribe(watch);
        return () => {
          off();
          stop();
          part.api.playing.step = null;
        };
      },
      state: (state: SequencerState) => rootState(state),
    }),
    row: slot<{ index: number }, SequencerRootState>({
      attrs: (state: SequencerState) => ({
        "data-disabled": flag(state.disabled),
        "data-painting": flag(state.painting),
        role: "group",
      }),
      props: { index: "key" },
      state: (state: SequencerState) => rootState(state),
    }),
    velocity: slot<AtStep, VelocityState>({
      attrs: (state: SequencerState, { props }) => {
        const cell = addressOf(props);
        const velocity = velocityAt(state.velocities, cell);
        return {
          "data-disabled": flag(state.disabled),
          "data-on": flag(isOn(state.value, cell)),
          "data-velocity": String(velocity),
          style: css({
            "--sequencer-velocity": String(velocity),
            "touch-action": "none",
          }),
        };
      },
      bind: (el, part) => {
        const key = cellKey(addressOf(part.props));
        part.api.velocities.set(key, el);
        return () => part.api.velocities.delete(key);
      },
      on: {
        // A press draws the velocity where the pointer is, and a drag draws across the row; Alt brings it back to full.
        pointerdown: (event, { api, el, props, store }) => {
          const root = rootOf(el);
          if (!root || store.get().disabled || event.button !== 0) {
            return;
          }
          event.preventDefault();
          el?.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
            preventScroll: true,
          });
          const cell = addressOf(props);
          if (event.altKey) {
            api.setVelocity(cell, DEFAULT_VELOCITY, "reset", event);
            return;
          }
          api.pressVelocity(cell, event, root);
        },
      },
      props: { cell: "key", row: "number", step: "number" },
      state: (state: SequencerState, { props }) => {
        const cell = addressOf(props);
        return {
          disabled: state.disabled,
          on: isOn(state.value, cell),
          velocity: velocityAt(state.velocities, cell),
        };
      },
    }),
    // The native range input of a velocity bar: it takes the keys and carries the name.
    velocityInput: slot<{
      cell: string;
      getAriaValueText?: (velocity: number) => string;
      row: number;
      step: number;
    }>({
      attrs: (state: SequencerState, { props }) => {
        const velocity = velocityAt(state.velocities, addressOf(props));
        return {
          "aria-valuetext": props.getAriaValueText
            ? props.getAriaValueText(velocity)
            : `${Math.round(velocity * 100)}%`,
          disabled: flag(state.disabled),
          max: "1",
          min: "0",
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(velocity),
        };
      },
      // `step` is set once, as a property: in the attributes it would share its name with this part's own `step` prop, which the custom element re-renders on without end.
      bind: (el) => {
        (el as HTMLInputElement).step = "any";
      },
      on: {
        change: (event, { api, el, props }) =>
          api.setVelocity(
            addressOf(props),
            Number((el as HTMLInputElement).value),
            "input-change",
            event
          ),
        keydown: (event, { api, props, store }) => {
          if (store.get().disabled) {
            return;
          }
          const cell = addressOf(props);
          if (event.key === "Delete" || event.key === "Backspace") {
            event.preventDefault();
            api.setVelocity(cell, DEFAULT_VELOCITY, "reset", event);
            return;
          }
          const velocity = velocityAt(store.get().velocities, cell);
          const target = {
            ArrowDown: velocity - VELOCITY_STEP,
            ArrowLeft: velocity - VELOCITY_STEP,
            ArrowRight: velocity + VELOCITY_STEP,
            ArrowUp: velocity + VELOCITY_STEP,
            End: 1,
            Home: 0,
            PageDown: velocity - VELOCITY_LARGE_STEP,
            PageUp: velocity + VELOCITY_LARGE_STEP,
          }[event.key];
          if (target === undefined) {
            return;
          }
          event.preventDefault();
          api.setVelocity(cell, target, "keyboard", event);
        },
      },
      // Written by the adapter from its velocity bar, so the input is the step's own.
      props: {
        cell: "key",
        getAriaValueText: "value",
        row: "number",
        step: "number",
      },
    }),
  }),
  state: (options: SequencerPrimitiveOptions): SequencerState => ({
    disabled: options.disabled ?? false,
    draftValue: null,
    draftVelocities: null,
    painting: false,
    source: options.source,
    tabStop: { row: 0, step: 0 },
    value: options.value ?? options.defaultValue ?? EMPTY,
    velocities: options.velocities ?? options.defaultVelocities ?? EMPTY,
  }),
  sync: optionsState,
});

import { createParts } from "@ui-sdk/vue/primitive";
import { defineComponent, h } from "vue";
import { sequencer, type VelocityState } from "./core";

/** Which element each part is. */
const parts = createParts(sequencer, {
  cell: "button",
  root: "div",
  row: "div",
  velocity: "div",
  velocityInput: "input",
});

/** One step of a row: a toggle button, pressed when the step is on. */
const Cell = defineComponent(
  (props: { row: number; step: number }, { attrs, slots }) =>
    () =>
      h(
        parts.Cell,
        {
          ...attrs,
          cell: `${props.row}:${props.step}`,
          row: props.row,
          step: props.step,
        },
        slots
      ),
  { inheritAttrs: false, name: "SequencerCell", props: ["row", "step"] }
);

/**
 * How loud one step plays, as a bar whose height is the `--sequencer-velocity`
 * CSS variable, with the native range input that carries its name inside it.
 */
const Velocity = defineComponent(
  (
    props: {
      getAriaValueText?: (velocity: number) => string;
      row: number;
      step: number;
    },
    { attrs, slots }
  ) =>
    () => {
      const { "aria-label": label, ...rest } = attrs;
      return h(
        parts.Velocity,
        {
          ...rest,
          cell: `${props.row}:${props.step}`,
          row: props.row,
          step: props.step,
        },
        {
          default: (scope: { state: VelocityState }) => [
            slots.default?.(scope),
            h(parts.VelocityInput, {
              "aria-label":
                (label as string | undefined) ?? `Step ${props.step + 1}`,
              cell: `${props.row}:${props.step}`,
              getAriaValueText: props.getAriaValueText,
              row: props.row,
              step: props.step,
            }),
          ],
        }
      );
    },
  {
    inheritAttrs: false,
    name: "SequencerVelocity",
    props: ["getAriaValueText", "row", "step"],
  }
);

/**
 * The rows, the cells and the velocity bars are written by the app, with
 * their `row` and `step`: the Root's default slot gets its state,
 * `{ rows, steps }`.
 */
export const Sequencer = { Cell, Root: parts.Root, Row: parts.Row, Velocity };
